def separar_natureza_forma_controle(apps, schema_editor):
    Insumo = apps.get_model('insumos', 'Insumo')
    atualizados = []
    for insumo in Insumo.objects.select_related('categoria').iterator():
        categoria = (insumo.categoria.nome or '').strip().casefold()
        if categoria == 'epi':
            insumo.natureza = 'EPI'
        elif insumo.tipo_controle == 'REUTILIZAVEL':
            insumo.natureza = 'REUTILIZAVEL'
        else:
            insumo.natureza = 'CONSUMIVEL'

        insumo.forma_controle = (
            'LOTE' if insumo.tipo_controle == 'LOTE' else 'QUANTIDADE'
        )
        atualizados.append(insumo)

    if atualizados:
        Insumo.objects.bulk_update(
            atualizados,
            fields=('natureza', 'forma_controle'),
            batch_size=500,
        )


